\begin{frame}{}
\begin{center}
\Large How do we identify features in Transformers?
\end{center}

\note{
\begin{itemize}
\item How do we identify features in a transformer?
\item Gathering ideas from the audience, specifically people who have not heard much about MechInterp before
\end{itemize}
}
\end{frame}

\begin{frame}{Getting a Feature Direction}
\textbf{Contrastive pairs:}
\[ r = \text{Emb}(\text{``Spanish''}) - \text{Emb}(\text{``French''}) \]

\vspace{0.5em}
\textbf{Linear probe:} \quad {\small $x_i$: sample activation, $y_i \in \{+1, -1\}$: label}
\[ r = \arg\max_{\|r\|=1} \sum_i y_i \cdot r^\top x_i \]

\vspace{0.5em}
\textbf{CAA:} \quad {\small $x_i^{(+)}, x_i^{(-)}$: positive/negative example of a property}
\[ r = \frac{1}{N} \sum_{i=1}^{N} \left( x_i^{(+)} - x_i^{(-)} \right) \]

\note{
\begin{itemize}
\item Preview: three families of methods for obtaining a feature direction
\item Contrastive pairs: just subtract embeddings of paired concepts
\item Linear probe: supervised training on labeled examples
\item CAA: averaged activation differences across many contrastive examples
\item We will see concrete examples of each in the following slides
\end{itemize}
}
\end{frame}

\begin{frame}{What To Do with a Feature Direction}
\textbf{Activation addition} (steering):
\[ x' \leftarrow x + \alpha \cdot r \]

\vspace{0.5em}
\textbf{Direction ablation} (make the model blind to the concept):
\[ x' \leftarrow x - \hat{r}\hat{r}^\top x \]

\vspace{0.5em}
\textbf{Probing} (read out a concept):
\[ s = r^\top x \]

\vspace{0.3em}
{\small $r$: feature direction \quad $x$: activation \quad $\alpha$: steering strength}

\note{
\begin{itemize}
\item Once we have a direction, there are three things we can do with it
\item Steering: add it to activations to push the model toward the concept
\item Ablation: project it out to make the model blind to the concept
\item Probing: read off the dot product to detect whether the concept is present
\end{itemize}
}
\end{frame}

\begin{frame}{Linear Probes Can Classify Text Properties}
\paperfig{figures/park2024/fig3.png}{03_transformer_features/figures/park2024/fig3-caption.txt}

\source{park2024}

\note{
\begin{itemize}
\item We can extract an English vs Spanish feature by embedding the words, subtracting them, and projecting on that direction
\item Doing that with a random word pair does not give you this distinction
\item This gives us evidence that human-understandable features exist in LLMs, and it seems somewhat easy to guess what they are
\item However, this just shows us we can extract a feature of the text
\item LLMs are not only cool because they model texts, they are also entities that reason and model the world
\item Can we extract these world-models from a transformer via finding the right feature directions?
\end{itemize}
}
\end{frame}

\begin{frame}{Linear Probes Can Measure World Models}
\paperfig{figures/nanda2023/fig0.png}{03_transformer_features/figures/nanda2023/fig0-caption.txt}

\source{nanda2023}

\note{
\begin{itemize}
\item Othello-GPT: a transformer trained as a next token predictor on moves in an Othello game
\item They train linear probes on the residual stream to predict the state of each field on the board
\item One probe each for empty, ``mine'' (player whose turn it is), and ``yours'' (other player's pieces)
\end{itemize}
}
\end{frame}

\begin{frame}{Linear Probes Can Measure World Models}
\paperfig{figures/nanda2023/table0.png}{03_transformer_features/figures/nanda2023/table0-caption.txt}

\source{nanda2023}

\note{
\begin{itemize}
\item They could reconstruct the state of the game board with pretty high accuracy
\item The model linearly encodes board state relative to the current player (MINE vs YOURS, not BLACK vs WHITE)
\end{itemize}
}
\end{frame}

\begin{frame}{Intervening on the World Model}
\paperfig{figures/nanda2023/fig1.png}{03_transformer_features/figures/nanda2023/fig1-caption.txt}

\source{nanda2023}

\note{
\begin{itemize}
\item Once they knew the direction, they could add it in to change the model's beliefs about what piece is there
\item They added the direction encoding a particular game state in every layer of the residual stream
\end{itemize}
}
\end{frame}

\begin{frame}{Intervening on the World Model}
\paperfig{figures/nanda2023/table1.png}{03_transformer_features/figures/nanda2023/table1-caption.txt}

\source{nanda2023}

