\begin{frame}{Logit Lens}
\begin{center}
\includegraphics[width=0.9\textwidth,height=0.75\textheight,keepaspectratio]{figures/nostalgebraist2020/logit_lens_kl_grid.png}
\end{center}

\source{nostalgebraist2020}

\note{
\begin{itemize}
\item We already have a translation from residual stream activations into tokens: the unembedding matrix
\item While only trained on the final activations, we can apply it to any layer's residual stream
\item There is no a priori reason this has to be meaningful, but it turns out that unembedding earlier residual states gives useful guesses for the next token, building up layer by layer
\item We can thereby see what aspects of the prediction are computed in which layer
\end{itemize}
}
\end{frame}

