\begin{frame}{Sparse Autoencoders}
\paperfig{figures/bricken2023/fig2.png}{03_transformer_features/figures/bricken2023/fig2-caption.txt}

\source{bricken2023}

\note{
\begin{itemize}
\item The idea: train a second neural network to represent the internals of the transformer
\item Each forward pass of the transformer gives us training data for the SAE
\end{itemize}
}
\end{frame}

\begin{frame}{Sparse Autoencoders}
\[ f = \text{ReLU}(W_{\text{enc}}(x - b_{\text{dec}}) + b_{\text{enc}}) \qquad \hat{x} = W_{\text{dec}} f + b_{\text{dec}} \]
\[ \mathcal{L} = \underbrace{\|x - \hat{x}\|_2^2}_{\text{reconstruction}} + \lambda \underbrace{\|f\|_1}_{\text{sparsity}} \]

\begin{center}
\begin{tikzpicture}[x=3.4cm,y=0.42cm,neuron/.style={circle,draw,fill=white,minimum size=9pt,inner sep=0pt},lbl/.style={font=\footnotesize},edge/.style={gray!60,thin}]
